<?php
require_once 'check_auth.php';
require_once '../config/database.php';
require_once '../config/inventory_service.php';
require_once '../config/system_settings.php';

ensure_inventory_schema($conn);
$systemLogo = system_logo_path($conn);
$summaryResult = $conn->query("SELECT COUNT(*) total_items, COALESCE(SUM(quantity),0) total_units, SUM(quantity <= minimum_stock AND quantity > 0) low_stock, SUM(quantity = 0) out_of_stock, COALESCE(SUM(quantity * unit_price),0) stock_value FROM inventory_items");
$summary = $summaryResult ? $summaryResult->fetch_assoc() : [];
$items = $conn->query("SELECT i.*, a.full_name updated_by_name FROM inventory_items i LEFT JOIN admin_users a ON a.admin_id=i.updated_by ORDER BY (i.quantity=0) DESC,(i.quantity<=i.minimum_stock) DESC,i.category,i.item_name");
$movements = $conn->query("SELECT m.*,i.item_code,i.item_name,a.full_name staff_name FROM inventory_movements m LEFT JOIN inventory_items i ON i.id=m.item_id LEFT JOIN admin_users a ON a.admin_id=m.staff_id ORDER BY m.created_at DESC LIMIT 15");
?>
