rrow-up-right-from-square"></i>Open staff inventory</a></div>
<div class="stats"><article class="stat"><i class="fas fa-box"></i><strong><?php echo (int)($summary['total_items']??0); ?></strong><span>Items</span></article><article class="stat"><i class="fas fa-layer-group"></i><strong><?php echo number_format((int)($summary['total_units']??0)); ?></strong><span>Total units</span></article><article class="stat"><i class="fas fa-triangle-exclamation" style="color:var(--amber)"></i><strong><?php echo (int)($summary['low_stock']??0); ?></strong><span>Low stock</span></article><article class="stat"><i class="fas fa-circle-xmark" style="color:var(--red)"></i><strong><?php echo (int)($summary['out_of_stock']??0); ?></strong><span>Out of stock</span></article><article class="stat"><i class="fas fa-peso-sign" style="color:var(--aqua)"></i><strong>₱<?php echo number_format((float)($summary['stock_value']??0),2); ?></strong><span>Stock value</span></article></div>
<section class="panel"><div class="panel-head">Current Inventory <span>Updated live</span></div><div class="table-wrap"><table><thead><tr><th>Item</th><th>Category</th><th>Stock</th><th>Minimum</th><th>Unit price</th><th>Status</th><th>Updated by</th></tr></thead><tbody><?php if($items&&$items->num_rows):while($item=$items->fetch_assoc()):$qty=(int)$item['quantity'];$min=(int)$item['minimum_stock'];$state=$qty===0?'out':($qty<=$min?'low':'good');$label=$qty===0?'Out of stock':($qty<=$min?'Low stock':'In stock');?><tr><td><strong><?php echo htmlspecialchars($item['item_name']); ?></strong><div class="muted"><?php echo htmlspecialchars($item['item_code']); ?></div></td><td><?php echo htmlspecialchars($item['category']); ?></td><td><strong><?php echo number_format($qty); ?></strong></td><td><?php echo number_format($min); ?></td><td>₱<?php echo number_format((float)$item['unit_price'],2); ?></td><td><span class="badge <?php echo $state; ?>"><?php echo $label; ?></span></td><td><?php echo htmlspecialchars($item['updated_by_name']?:($item['updated_by']?:'System')); ?><div class="muted"><?php echo date('M d, Y h:i A',strtotime($item['updated_at'])); ?></div></td></tr><?php endwhile;else:?><tr><td colspan="7">No inventory items found.</td></tr><?php endif;?></tbody></table></div></section>
<section class="panel"><div class="panel-head">Recent Staff Movements <span>Last 15 changes</span></div><div class="table-wrap"><table><thead><tr><th>Item</th><th>Movement</th><th>Before / After</th><th>Reason</th><th>Staff</th><th>Date</th><th></th></tr></thead><tbody><?php if($movements&&$movements->num_rows):while($m=$movements->fetch_assoc()):?><tr><td><strong><?php echo htmlspecialchars($m['item_name']?:'Deleted item'); ?></strong><div class="muted"><?php echo htmlspecialchars($m['item_code']??''); ?></div></td><td class="<?php echo (int)$m['quantity_change']>=0?'plus':'minus'; ?>"><?php echo (int)$m['quantity_change']>=0?'+':'';echo (int)$m['quantity_change']; ?></td><td><?php echo (int)$m['previous_quantity']; ?> → <?php echo (int)$m['new_quantity']; ?></td><td><?php echo htmlspecialchars($m['reason']?:'—'); ?></td><td><?php echo htmlspecialchars($m['staff_name']?:$m['staff_id']); ?></td><td><?php echo date('M d, Y',strtotime($m['created_at'])); ?><div class="muted"><?php echo date('h:i A',strtotime($m['created_at'])); ?></div></td><td></td></tr><?php endwhile;else:?><tr><td colspan="7">No stock movements recorded.</td></tr><?php endif;?></tbody></table></div></section></section></main></div></body></html>
